@Test
void upstreamUrlIsRequired() throws IOException {
    assertRejected("api.token=s3cret\n", "upstream.url: is required");
}

@Test
void rejectsAWorkerCountThatIsNotANumber() throws IOException {
    assertRejected(REQUIRED + "worker.threads=1o\n", "worker.threads", "\"1o\"");
}

@Test
void rejectsValuesBelowTheMinimum() throws IOException {
    assertRejected(REQUIRED + "worker.threads=0\n", "worker.threads", "at least 1");
    assertRejected(REQUIRED + "queue.capacity=-5\n", "queue.capacity", "at least 1");
    assertRejected(REQUIRED + "retry.max-attempts=-1\n", "retry.max-attempts", "at least 0");
}

@Test
void rejectsATimeoutWithoutAUnit() throws IOException {
    assertRejected(REQUIRED + "request.timeout=30\n", "request.timeout", "\"30\"");
}

@Test
void rejectsAZeroTimeout() throws IOException {
    assertRejected(REQUIRED + "request.timeout=0s\n", "request.timeout");
}

@Test
void rejectsAMetricsFlagThatIsNotTrueOrFalse() throws IOException {
    assertRejected(REQUIRED + "metrics.enabled=yes\n", "metrics.enabled", "true or false");
}

@Test
void rejectsAnUpstreamThatIsNotAnHttpUrl() throws IOException {
    assertRejected("api.token=s3cret\nupstream.url=uplink.example.com\n", "upstream.url");
    assertRejected("api.token=s3cret\nupstream.url=ht tp://bad\n", "upstream.url");
}

@Test
void rejectsUnknownKeysSoMisspellingsAreCaught() throws IOException {
    assertRejected(REQUIRED + "worker.thread=8\n", "worker.thread: unknown key");
}

@Test
void reportsEveryProblemAtOnce() throws IOException {
    ConfigException error = assertThrows(
            ConfigException.class,
            () -> ConfigLoader.load(write("worker.threads=four\nrequest.timeout=30\n")));

    assertEquals(4, error.problems().size(), error.getMessage());
}

@Test
void doesNotPutTheTokenInTheMessage() throws IOException {
    ConfigException error = assertThrows(
            ConfigException.class, () -> ConfigLoader.load(write(REQUIRED + "worker.threads=x\n")));

    assertFalse(error.getMessage().contains("s3cret"));
}

@Test
void aMissingFileIsAnError() {
    ConfigException error = assertThrows(
            ConfigException.class, () -> ConfigLoader.load(dir.resolve("absent.properties")));

    assertTrue(error.getMessage().contains("absent.properties"), error.getMessage());
    assertTrue(error.getMessage().contains("not found"), error.getMessage());
}

private void assertRejected(String content, String... expectedFragments) throws IOException {
    Path file = write(content);
    ConfigException error = assertThrows(ConfigException.class, () -> ConfigLoader.load(file));
    for (String fragment : expectedFragments) {
        assertTrue(error.getMessage().contains(fragment), error.getMessage());
    }
}

